function minInsertions(s) {
  // n minus the longest common subsequence of s and its reverse (the longest palindromic subsequence).
  const r = s.split('').reverse().join('');
  const n = s.length;
  let prev = new Array(n + 1).fill(0);
  for (let a = 1; a <= n; a++) {
    const row = new Array(n + 1).fill(0);
    for (let b = 1; b <= n; b++) row[b] = s[a - 1] === r[b - 1] ? prev[b - 1] + 1 : Math.max(prev[b], row[b - 1]);
    prev = row;
  }
  return n - prev[n];
}

