function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 400 + pick(101) : 1 + pick(10);
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, [1, 2, 3, 5, 26][pick(5)]);
  const chars = Array.from({ length: n }, () => letters[pick(letters.length)]);
  const roll = rand();
  if (roll < 0.3) {
    // Mirror the first half to start from a palindrome, then maybe break a few spots.
    for (let i = 0; i < n >> 1; i++) chars[n - 1 - i] = chars[i];
    const breaks = pick(large ? 20 : 3);
    for (let t = 0; t < breaks; t++) chars[pick(n)] = letters[pick(letters.length)];
  }
  return [chars.join('')];
}
